def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    strong_prev = []
    moderate_prev = []
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 90:
                strong_prev.append(float(bid))
            elif float(bid) >= 40:
                moderate_prev.append(float(bid))

    max_prev = max(prev_bids) if prev_bids else 0.0
    max_moderate = max(moderate_prev) if moderate_prev else 0.0
    min_strong = min(strong_prev) if strong_prev else 9999.0

    scarcity = 1.0 - ((float(supply) - 15.0) / 10.0)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 6:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.45

    urgency += scarcity * 0.55

    if urgency >= 1.6:
        bid = max(DAILY_SALARY * 0.95, max_moderate + 6.0)
        if min_strong < 9999.0:
            bid = max(bid, min_strong + 1.0)
    elif urgency >= 1.0:
        anchor = max(42.0, max_moderate + 2.5)
        if scarcity > 0.7:
            anchor += 8.0
        bid = anchor
    elif urgency >= 0.5:
        if supply >= 22:
            bid = 18.0
        elif supply >= 19:
            bid = 28.0
        else:
            bid = max(34.0, max_moderate)
    else:
        if supply >= 22:
            bid = 8.0
        elif supply >= 20:
            bid = 15.0
        else:
            bid = 24.0

    if max_prev >= 120 and urgency < 1.6:
        bid = min(bid, 36.0)

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.72)
    elif budget < DAILY_SALARY * 2.0:
        bid = min(bid, budget * 0.82)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    if day >= 8 and hp >= 7 and supply >= 20:
        bid = min(bid, 20.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline: if my hp is low or I've already missed water, bid aggressively
    pressure = 0.0
    if hp <= 2:
        pressure += 1.0
    if no_water_days >= 1:
        pressure += 0.6
    if hp <= 4:
        pressure += 0.4

    # Determine opponent pressure from yesterday
    if prev_bids:
        highest_prev = max(prev_bids)
        # If someone heavily outbid yesterday, raise slightly to contest.
        if highest_prev >= DAILY_SALARY * 0.85:
            base = DAILY_SALARY * (0.35 + 0.25 * pressure)
        elif highest_prev >= DAILY_SALARY * 0.6:
            base = highest_prev * (0.75 + 0.15 * pressure)
        else:
            base = max(DAILY_SALARY * 0.45, highest_prev + 2.0) * (0.9 + 0.1 * pressure)
    else:
        base = DAILY_SALARY * (0.55 + 0.2 * pressure)

    # Supply-aware adjustment: when supply is tighter, bid higher.
    # supply is float; map to a 0..1 tightness score.
    tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (float(MAX_SUPPLY) - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
    tightness = max(0.0, min(1.0, tightness))

    base = base * (0.85 + 0.3 * tightness)

    # Keep within reasonable bounds to avoid going broke.
    # If budget is low, cap at budget.
    target = max(0.0, min(budget, base))

    # If budget is extremely low, still try to secure water when hp is critical.
    if budget <= DAILY_SALARY * 0.15:
        if hp <= 2 or no_water_days >= 1:
            target = max(0.0, min(budget, DAILY_SALARY * 0.95))
        else:
            target = max(0.0, min(budget, DAILY_SALARY * 0.35))

    # Final guard: never bid negative.
    return float(max(0.0, target))

